scripts.杨瑛的同伴对话.txt:
// 杨瑛的同伴对话

	If ($Event == 610) @Event610;
	Return;
	
@Event610:	
	Say("杨瑛：好痛快！想不到湖底竟有这么美！独孤大哥，我很久没有这么开心过了！", 39);
	Return;

traps.trap01.txt:
// 切换到map098天王帮秘道

	If ($Event == 610) @Event610;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map098_天王帮秘道.map");
	LoadNpc("map098.npc");
	SaveNpc("temp_map098.npc");  //有反复战斗
	LoadObj("map098.obj");
	SetPlayerPos(17, 20);
	SetPlayerDir(3);
	FadeIn();
	Return;
	
@Event610:
	FadeOut();
	SaveNpc();
