traps.trap02.txt:
// 切换到map121洞庭湖底

	If ($Event == 560) @Event560;
	Return;

@Event560:	
	Say("独孤剑：怎么会没有船，难道要游到岛上去？", 8);
	Say("独孤剑：嘻嘻，倒是个不错的主意！", 2);
	SetPlayerDir(1);
	SetNpcActionFile("独孤剑", 0, "");
	SetNpcActionFile("独孤剑", 1, "");
	NpcSpecialAction("独孤剑", "mpc040.asf");
	Sleep(1200);
	PlaySound("特_落水.wav");
		
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("战斗.mp3");
	LoadMap("map121_洞庭湖底.map");
	LoadNpc("map121.npc");
	SaveNpc("temp_map121.npc");  //有反复战斗
	LoadObj("map121.obj");
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	SetPlayerPos(2, 9);
	SetPlayerDir(7);
				
	NpcSpecialAction("独孤剑", "mpc041.asf");
	OpenWaterEffect();
	ChangeMapColor(150, 180, 255);
	ChangeAsfColor(150, 180, 255);
	DisableNpcAI();
	FadeIn();
	Say("独孤剑：哇！想不到洞庭湖底竟有这般景致！", 2);
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	EnableNpcAI();
	Return;
